\documentclass[border=5mm]{standalone}
\usepackage{pgfplots}
\usetikzlibrary {arrows.meta,bending}
\usepackage{tikz-3dplot}

\begin{document}

\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\pagestyle{empty}
\begin{tikzpicture}[scale=1.5, rotate=0]

\def\nsamples{24}

%%% Change this:
\def\mr{2} % Marks on axes (Rho)

\def\thetaStart{90} % Start Theta
\def\thetaEnd{270} % End Theta

\def\phiStart{0} % Start Phi
\def\phiEnd{180} % End Phi

\begin{axis}[
		scale=1,
		clip=false,
		view={120}{20},
		hide axis,
		xmin=-1.5,xmax=1.5,
		ymin=-1.5,ymax=1.5,
		zmin=-1.3,zmax=1.3,
	]

% Axes
\def\axwidth{0.6}

% Sphere
   \plot3[
   		surf,
		shader = faceted interp,
		opacity=1,
		samples = \nsamples,
		samples y=\nsamples,
		draw=lightgray, ultra thin,
		colormap={custom}{color(0)=(deepskyblue!1) color(1)=(deepskyblue!1)},
		z buffer=sort, domain=0:180, y domain=90:270]
	({1*sin(x)*cos(y)}, {1*sin(x)*sin(y)}, {1*cos(x)});

   \plot3[
   		surf,
		shader = faceted interp,
		opacity=1,
		samples = \nsamples/3,
		samples y=\nsamples,
		draw=lightgray, ultra thin,
		colormap={custom}{color(0)=(deepskyblue!1) color(1)=(deepskyblue!1)},
		z buffer=sort, domain=0:1, y domain=0:360]
	({0}, {x*cos(y)}, {x*sin(y)});


% X
\draw[line width=\axwidth/2, dashed, opacity=0.5] (axis cs:-1.5,0,0) -- (axis cs:0,0,0);
% Y
%\draw[line width=\axwidth] (axis cs:0,-1.5,0) -- (axis cs:0,-1,0);
%\draw[line width=\axwidth/2, dashed, opacity=0.5] (axis cs:0,-1,0) -- (axis cs:0,1,0);
% Z
%\draw[line width=\axwidth] (axis cs:0,0,-1.5) -- (axis cs:0,0,-1);
%\draw[line width=\axwidth/2, dashed, opacity=0.5] (axis cs:0,0,-1) -- (axis cs:0,0,1);

% X-cont.
\draw[line width=\axwidth, -stealth] (axis cs:0,0,0) -- (axis cs:2,0,0)
		node[left, xshift=4pt, yshift=-3pt] {\scriptsize $x$}; 	
% Y-cont.
\draw[line width=\axwidth, -stealth] (axis cs:0,-1.5,0) -- (axis cs:0,1.5,0)
		node[right, yshift=-2pt] {\scriptsize $y$};
% Z-cont.
\draw[line width=\axwidth, -stealth] (axis cs:0,0,-1.5) -- (axis cs:0,0,1.5)
		node[above] {\scriptsize $z$};  

% Ticks-X
\node[circle, draw=none, fill=black, inner sep=0.75pt, 
		label={[below, yshift=0pt, black]: \tiny $-\mr$}] 
			at (axis cs:-1,0,0) {};
%\node[circle, draw=none, fill=black, inner sep=0.75pt, 
%		label={[below, yshift=0pt, black]: \tiny $\mr$}] 
%			at (axis cs:1,0,0) {};

% Ticks-Y
\node[circle, draw=none, fill=black, inner sep=0.75pt, 
		label={[below, xshift=0pt, yshift=0pt, black]: \tiny $-\mr$}] 
			at (axis cs:0,-1,0) {};
\node[circle, draw=none, fill=black, inner sep=0.75pt, 
		label={[below, xshift=0pt, yshift=0pt, black]: \tiny $\mr$}] 
			at (axis cs:0,1,0) {};

 Ticks-Z
\node[circle, draw=none, fill=black, inner sep=0.75pt, 
		label={[left, xshift=1pt, yshift=-1pt, black]: \tiny $-\mr$}] 
			at (axis cs:0,0,-1) {};
\node[circle, draw=none, fill=black, inner sep=0.75pt, 
		label={[left, xshift=1pt, yshift=-1pt, black]: \tiny $\mr$}] 
			at (axis cs:0,0,1) {};

% Theta
\draw[color=orangepeel, line width=\axwidth*1.5, arrows={-[scale=0.75]>}] 
	plot[domain=\thetaStart+12:\thetaEnd-12, samples=180, variable=\t] 
		(axis cs:{0.3*cos(\t)},{0.3*sin(\t)},0);
\node[orangepeel!80!black, inner sep=0pt] at 
	(axis cs:{0.4*cos((\thetaStart+\thetaEnd)/2)},{0.4*sin((\thetaStart+\thetaEnd)/2)},0.1) 
		{\small $\theta$};

% Phi
\draw[color=fadedpink, line width=\axwidth*1.5, arrows={-[scale=0.75]>}] 
	plot[domain={\phiStart+6}:{\phiEnd-6}, samples=180, variable=\t] 
		(axis cs:0.02,{0.6*sin(\t)},{0.6*cos(\t)});
\node[fadedpink!80!black, inner sep=1pt] at 
	(axis cs:0.02,{0.72*sin((\phiStart+\phiEnd)/2)},{0.72*cos((\phiStart+\phiEnd)/2)}) 
		{\small $\phi$};

\end{axis}
\end{tikzpicture}
\end{document}
